@contextmanager
def live_view_operation_log_scope(
    path: Path,
    *,
    artifact_manifest_path: Path | None = None,
    output_root: Path | None = None,
) -> Iterator[None]:
    """Route scene-tool telemetry to launcher-owned viewer files."""

    global _LIVE_VIEW_OPERATION_LOG_PATH
    previous = _LIVE_VIEW_OPERATION_LOG_PATH
    _LIVE_VIEW_OPERATION_LOG_PATH = path.expanduser().absolute()
    try:
        yield
    finally:
        _LIVE_VIEW_OPERATION_LOG_PATH = previous


def packet_image_inputs(packet: dict[str, Any]) -> list[dict[str, str]]:
    """Return verified usd-cli render attachments from a workflow packet."""

    images: list[dict[str, str]] = []
    for record in packet.get("initial_evidence_renders", []):
        if not isinstance(record, dict):
            continue
        image_path = record.get("image_path")
        label = record.get("name")
        if (
            isinstance(image_path, str)
            and isinstance(label, str)
            and Path(image_path).is_file()
        ):
            images.append(
                {"label": f"usd-cli OVRTX render: {label}", "path": image_path}
            )
        segmentation_path = record.get("segmentation_path")
        if (
            isinstance(segmentation_path, str)
            and isinstance(label, str)
            and Path(segmentation_path).is_file()
        ):
            images.append(
                {
                    "label": f"usd-cli segmentation: {label}",
                    "path": segmentation_path,
                }
            )
    return images


