def _resolve_materials_usd_from_manifest(materials_yaml: Path) -> Path:
    """Resolve one material library path through the shared manifest contract."""

    try:
        payload = yaml.safe_load(materials_yaml.read_text(encoding="utf-8"))
    except (OSError, UnicodeError) as exc:
        raise ValueError(
            f"Failed to read material YAML manifest {materials_yaml}: {exc}"
        ) from exc
    except yaml.YAMLError as exc:
        raise ValueError(
            f"Failed to parse material YAML manifest {materials_yaml}: {exc}"
        ) from exc
    if not isinstance(payload, dict):
        raise ValueError(f"Material YAML manifest {materials_yaml} must be a mapping.")
    library_path = payload.get("library_path")
    if not isinstance(library_path, str) or not library_path.strip():
        raise ValueError(
            f"{materials_yaml} does not define a non-empty top-level library_path. "
            "Pass --materials-usd to override it."
        )
    resolved = Path(library_path).expanduser()
    if not resolved.is_absolute():
        resolved = materials_yaml.parent / resolved
    return resolved.resolve()


@dataclass(frozen=True)
class WatchdogFailure:
    reason: str
    fatal: bool = False


@dataclass(frozen=True)
class UsdCliTelemetryRoute:
    """Resolved package-owned ``usd-cli-tel`` telemetry route."""

    status: str
    wrapper_path: Path | None = None
    target_path: Path | None = None
    reason: str | None = None
    source_root: Path | None = None
    source_revision: str | None = None

    @property
    def active(self) -> bool:
        return self.status == "active"

    def metadata(self) -> dict[str, object]:
        return {
            "schema_version": USD_CLI_TELEMETRY_ROUTE_SCHEMA_VERSION,
            "mode": "explicit-package-wrapper",
            "status": self.status,
            "enabled": self.active,
            "wrapper_path": (
                str(self.wrapper_path) if self.wrapper_path is not None else None
            ),
            "target_path": (
                str(self.target_path) if self.target_path is not None else None
            ),
            "reason": self.reason,
        }


@dataclass(frozen=True)
class _UsdCliTelemetryRouteCache:
    """One config-owned route validation scoped to one workflow run."""

    run_dir: Path
    repo_root: Path
    route: UsdCliTelemetryRoute
    wrapper_identity: tuple[int, int, int, int, int]
    target_identity: tuple[int, int, int, int, int]


@dataclass(frozen=True)
class UsdCliDaemonIdentity:
    """Immutable OS and protocol identity captured before child write access."""

    pid: int
    process_start_token: str
    project_id: str
    instance_id: str | None
    process_group_id: int | None = None
    os_session_id: int | None = None


@dataclass
class UsdCliRunStateAnchor:
    """Held run/state directory inodes created before daemon launch.

    Descriptor ownership is mutable even though the captured inode identities are
    not.  Closing an anchor marks both descriptors invalid so cleanup retries can
    never close an unrelated descriptor after the OS recycles a number.
    """

    run_descriptor: int
    state_descriptor: int
    run_identity: tuple[int, int]
    state_identity: tuple[int, int]
    child_config_bytes: bytes
    external_lifecycle: bool
    allowed_roots: tuple[Path, ...]
    daemon_log_redaction_values: tuple[bytes, ...] = field(
        default_factory=tuple,
        repr=False,
    )
    run_context: Any | None = field(default=None, repr=False)
    state_context: Any | None = field(default=None, repr=False)
    run_root: Any | None = field(default=None, repr=False)
