class UsdCliDaemonStrictStartError(RuntimeError):
    """A strict daemon start failed after its state was cleaned or quarantined."""

    def __init__(
        self,
        message: str,
        *,
        teardown_evidence: UsdCliDaemonTeardownEvidence | None,
        cleanup_lease: UsdCliDaemonCleanupEvidence | None = None,
        interrupted: bool = False,
    ) -> None:
        super().__init__(message)
        self.teardown_evidence = teardown_evidence
        self.cleanup_lease = cleanup_lease
        self.interrupted = interrupted


def _workflow_usd_cli_session_id(*, workflow: str, project_dir: Path) -> str:
    """Return the deterministic named session shared by workflow and viewer."""

    project = project_dir.expanduser().resolve(strict=False)
    digest = hashlib.sha256(f"{workflow}:{project}".encode()).hexdigest()[:20]
    return f"workflow-{digest}"


def _attach_workflow_usd_cli_session(
    *,
    repo_root: Path,
    run_dir: Path,
    workflow: str,
    raw_directory_identity: tuple[int, int] | None = None,
) -> WorkflowUsdCliSession:
    """Bind a named workflow session to the already-started run daemon.

    Daemon state is created and authenticated by the launcher before this helper
    runs. Constructing the session directly avoids replacing that state/config
    and ensures all workflow turns reuse the same sidecar.
    """

    project_dir = run_dir.expanduser().resolve(strict=True)
    observed_state = read_contained_artifact(
        project_dir,
        project_dir / ".usd-cli" / "server.json",
        max_bytes=64 * 1024,
        capture_bytes=True,
    )
    assert observed_state.data is not None
    try:
        daemon_state = json.loads(observed_state.data)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError("Parent usd-cli daemon state is invalid") from exc
    if (
        not isinstance(daemon_state, dict)
        or daemon_state.get("host") != "127.0.0.1"
        or not isinstance(daemon_state.get("port"), int)
        or isinstance(daemon_state.get("port"), bool)
    ):
        raise RuntimeError("Parent usd-cli daemon endpoint is invalid")
    package_route = WorkflowUsdCliSession.preflight_package_route(
        repository_root=repo_root,
    )
    return WorkflowUsdCliSession(
        project_dir=project_dir,
        session_id=_workflow_usd_cli_session_id(
            workflow=workflow,
            project_dir=project_dir,
        ),
        route=package_route.route,
        workflow=workflow,
        daemon_project_dir=project_dir,
        daemon_server_url=f"http://127.0.0.1:{int(daemon_state['port'])}",
        receipt_checkpoint_sha256=_file_sha256(
            project_dir / "raw" / "usd_cli_command_receipts.checkpoint.json",
            within=project_dir,
        ),
        raw_directory_identity=raw_directory_identity,
        _package_route_pin=package_route,
    )


def _parent_usd_cli_artifact_identity(path: Path) -> ParentUsdCliArtifactIdentity:
    resolved = path.expanduser().resolve(strict=True)
    observed = read_contained_artifact(resolved.parent, resolved)
    return ParentUsdCliArtifactIdentity(
        path=str(observed.path),
        sha256=observed.sha256,
        size_bytes=observed.size_bytes,
    )


def _parent_usd_cli_allowed_roots(
    run_dir: Path,
    input_roots: tuple[Path, ...],
) -> tuple[Path, ...]:
    roots: list[Path] = [run_dir.expanduser().resolve(strict=True)]
    for raw_root in input_roots:
        resolved = raw_root.expanduser().resolve(strict=True)
        root = resolved if resolved.is_dir() else resolved.parent
        if root not in roots:
            roots.append(root)
    return tuple(roots)


def _write_shared_parent_usd_cli_session_identity(
    *,
    config: AgentRuntimeConfig,
    run_dir: Path,
    workflow: str,
    lease: UsdCliDaemonLease,
    session: WorkflowUsdCliSession,
    readiness: UsdCliReadiness,
    allowed_roots: tuple[Path, ...],
) -> tuple[Path, str, str]:
    """Publish the workflow-agnostic child capability for one live daemon."""

    if readiness.artifact_path is None:
        raise RuntimeError("Parent usd-cli readiness omitted its evidence artifact.")
    daemon = lease.identity
    if (
        daemon.instance_id is None
        or daemon.process_group_id is None
        or daemon.os_session_id is None
    ):
        raise RuntimeError("Parent usd-cli daemon omitted its complete OS identity.")
    try:
        state = json.loads(lease.server_state_bytes)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError("Parent usd-cli daemon state is invalid.") from exc
    if (
        not isinstance(state, dict)
        or state.get("host") != "127.0.0.1"
        or state.get("lifecycle_owner") != "external"
        or not isinstance(state.get("port"), int)
        or isinstance(state.get("port"), bool)
    ):
        raise RuntimeError("Parent usd-cli daemon is not externally owned.")
    launch_id = f"{workflow.replace('.', '-')}-{time.time_ns()}-{secrets.token_hex(4)}"
    identity = ParentUsdCliSessionIdentity(
        created_at=datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        launch_id=launch_id,
        workflow=workflow,
        run_id=run_dir.name,
        run_dir=str(run_dir.resolve(strict=True)),
        repository_root=str(config.repo_root.expanduser().resolve(strict=True)),
        parent_session_id=session.session_id,
        project_id=daemon.project_id,
        instance_id=daemon.instance_id,
        daemon_identity_sha256=parent_usd_cli_daemon_identity_sha256(
            pid=daemon.pid,
            process_start_token=daemon.process_start_token,
            project_id=daemon.project_id,
            instance_id=daemon.instance_id,
            process_group_id=daemon.process_group_id,
            os_session_id=daemon.os_session_id,
        ),
        server_host="127.0.0.1",
        server_port=int(state["port"]),
        allowed_roots=[str(root) for root in allowed_roots],
        readiness_artifact=_parent_usd_cli_artifact_identity(readiness.artifact_path),
        launcher_implementation=_parent_usd_cli_artifact_identity(
            Path(__file__).resolve(strict=True)
        ),
        usd_cli_version=readiness.version,
        usd_cli_source_revision=readiness.source_revision,
        usd_cli_wrapper=str(session.route.wrapper.resolve(strict=True)),
        usd_cli_executable=str(session.route.target.resolve(strict=True)),
    )
    identity_path = run_dir / "raw" / f"parent_usd_cli_session_{launch_id}.json"
    atomic_write_json(identity_path, identity, within=run_dir)
    return (
        identity_path,
        file_sha256(identity_path),
        f"http://127.0.0.1:{int(state['port'])}",
    )


def start_parent_usd_cli_capability(
    *,
    config: AgentRuntimeConfig,
    run_dir: Path,
    workflow: str,
    session_workflow: str | None = None,
    input_roots: tuple[Path, ...] = (),
    initial_scene: Path | None = None,
    required_capabilities: tuple[str, ...] = (),
    timeout_seconds: float = 900.0,
    raw_directory_identity: tuple[int, int] | None = None,
    pinned_render_config: Mapping[str, object] | None = None,
    pinned_render_backend_api_keys: Mapping[str, str] | None = None,
) -> ParentUsdCliCapability:
    """Start and attest the single GPU-capable daemon for a child workflow."""

    _validate_parent_managed_child_confinement(
        config,
        capability_will_start=True,
    )
    resolved_run = run_dir.expanduser().resolve(strict=True)
    allowed_roots = _parent_usd_cli_allowed_roots(resolved_run, input_roots)
    route = _workflow_usd_cli_telemetry_route(config, resolved_run)
    if not route.active or route.target_path is None:
        raise RuntimeError(
            route.reason or "The package-owned usd-cli-tel route is unavailable."
        )
    lease: UsdCliDaemonLease | None = None
    try:
        daemon_start_kwargs: dict[str, Any] = {}
        if pinned_render_config is not None:
            daemon_start_kwargs["pinned_render_config"] = pinned_render_config
        if pinned_render_backend_api_keys is not None:
            daemon_start_kwargs["pinned_render_backend_api_keys"] = (
                pinned_render_backend_api_keys
            )
        lease = _start_usd_cli_run_daemon(
            route=route,
            run_dir=resolved_run,
            idle_timeout_seconds=_usd_cli_daemon_idle_timeout_seconds(
                config.child_timeout_seconds
            ),
            external_lifecycle=True,
            allowed_roots=allowed_roots,
            **daemon_start_kwargs,
        )
        session = _attach_workflow_usd_cli_session(
            repo_root=config.repo_root,
            run_dir=resolved_run,
            workflow=session_workflow or workflow,
            raw_directory_identity=raw_directory_identity,
        )
        readiness = ensure_usd_cli_ovrtx_ready(
            config.repo_root,
            run_dir=resolved_run,
            executable=route.target_path,
            timeout_seconds=timeout_seconds,
            required_capabilities=required_capabilities,
            session=session,
        )
        if initial_scene is not None:
            # The bootstrap handle is inspection-only.  A writable open here would
            # claim the shared root layer and block isolated workflow sessions from
            # opening the same input.  Authoring operations explicitly reopen their
            # working scene writable when they begin.
            session.open(initial_scene, read_only=True)
        _activate_usd_cli_child_config(lease)
        identity_path, identity_sha256, server_url = (
            _write_shared_parent_usd_cli_session_identity(
                config=config,
                run_dir=resolved_run,
                workflow=workflow,
                lease=lease,
                session=session,
                readiness=readiness,
                allowed_roots=allowed_roots,
            )
        )
        return ParentUsdCliCapability(
            route=route,
            lease=lease,
            session=session,
            readiness=readiness,
            identity_path=identity_path,
            identity_sha256=identity_sha256,
            server_url=server_url,
        )
    except BaseException as startup_exc:
        if lease is not None:
            try:
                _stop_usd_cli_run_daemon_best_effort(lease=lease)
            except BaseException as cleanup_exc:
                cleanup_summary = str(cleanup_exc) or type(cleanup_exc).__name__
                # Strict cleanup retains descriptor authority across Ctrl-C for
                # an owning caller to retry. Startup failure returns no lease,
                # so release that authority and preserve the original failure.
                if lease.state_anchor is not None:
                    try:
                        _close_usd_cli_run_state_anchor(lease.state_anchor)
                    except Exception as close_exc:  # noqa: BLE001
                        cleanup_exc.add_note(
                            f"usd-cli state-anchor cleanup also failed: {close_exc}"
                        )
                logger.warning(
                    "Parent usd-cli cleanup was interrupted during startup failure: %s",
                    cleanup_summary,
                    exc_info=True,
                )
                startup_exc.add_note(
                    f"parent usd-cli cleanup was also interrupted: {cleanup_summary}"
                )
        raise


def bind_parent_usd_cli_capability(
    config: AgentRuntimeConfig,
    capability: ParentUsdCliCapability,
) -> AgentRuntimeConfig:
    """Return a child config that can reuse, but never replace, the parent daemon."""

    bound = replace(
        config,
        parent_usd_cli_session_identity=capability.identity_path,
        parent_usd_cli_session_identity_sha256=capability.identity_sha256,
        usd_cli_server_url=_validate_parent_usd_cli_server_url(capability.server_url),
    )
    return bound


def stop_parent_usd_cli_capability(capability: ParentUsdCliCapability) -> None:
    _stop_usd_cli_run_daemon_best_effort(lease=capability.lease)


def stop_parent_usd_cli_capability_strict(
    capability: ParentUsdCliCapability,
) -> UsdCliDaemonTeardownEvidence:
    """Release a parent capability and return its complete teardown proof."""

    return _stop_usd_cli_run_daemon_strict(lease=capability.lease)


def parent_usd_cli_prompt_contract(capability: ParentUsdCliCapability) -> str:
    return (
        "\n\n## Parent-owned usd-cli session\n\n"
        f"- Server: `{capability.server_url}`\n"
        f"- Session: `{capability.session.session_id}`\n"
        f"- Typed identity: `{capability.identity_path}`\n\n"
        "The launcher owns the only renderer-capable usd-cli daemon. Use the "
        "supplied session for every usd-cli command. Do not start, stop, restart, "
        "or locally probe a renderer.\n"
    )


