@dataclass
class _BridgeModelUsageLedger:
    """Parent-memory usage records captured at trusted bridge boundaries."""

    results: list[dict[str, Any]] = field(default_factory=list)

    def record(self, payload: dict[str, Any]) -> None:
        result: dict[str, Any] = {}
        usage = payload.get("usage")
        if isinstance(usage, dict):
            result["usage"] = {
                key: value
                for key, value in usage.items()
                if isinstance(value, int) and not isinstance(value, bool)
            }
        reported_cost = payload.get("total_cost_usd")
        if isinstance(reported_cost, int | float) and not isinstance(
            reported_cost, bool
        ):
            result["total_cost_usd"] = float(reported_cost)
        self.results.append(result)

    def snapshot(self) -> list[dict[str, Any]]:
        return [
            {
                key: dict(value) if isinstance(value, dict) else value
                for key, value in result.items()
            }
            for result in self.results
        ]


def _bridge_model_usage_ledger(
    config: AgentRuntimeConfig,
    run_dir: Path | None = None,
) -> _BridgeModelUsageLedger:
    """Return the per-run trusted ledger for every shared runtime config."""

    if run_dir is not None:
        run_key = _lexical_absolute_path(run_dir)
        if getattr(config, "_bridge_model_usage_run_dir", None) != run_key:
            object.__setattr__(config, "_bridge_model_usage", _BridgeModelUsageLedger())
            object.__setattr__(config, "_bridge_model_usage_run_dir", run_key)
    ledger = getattr(config, "_bridge_model_usage", None)
    if isinstance(ledger, _BridgeModelUsageLedger):
        return ledger
    ledger = _BridgeModelUsageLedger()
    # The shared launcher is also used by frozen configs owned by scene, asset,
    # texture, and segmentation runners. Attach the private runtime-only state
    # without requiring those public config contracts to expose billing fields.
    object.__setattr__(config, "_bridge_model_usage", ledger)
    return ledger


def _reset_bridge_model_usage_ledger(config: AgentRuntimeConfig) -> None:
    """Scope trusted bridge accounting to one top-level run invocation."""

    object.__setattr__(config, "_bridge_model_usage", _BridgeModelUsageLedger())
    object.__setattr__(config, "_bridge_model_usage_run_dir", None)


