    codex_sandbox_mode: str = CODEX_SANDBOX_WORKSPACE_WRITE
    codex_config: dict[str, object] | None = None
    vision_backend: str | None = None
    vision_model: str | None = None
    vision_api_key_env: str | None = None
    vision_base_url: str | None = None
    vision_max_tokens: int = 4096
    claude_config: dict[str, object] | None = None
    claude_permission_mode: str = "default"
    claude_max_turns: int | None = None
    claude_execution_mode: str = CLAUDE_EXECUTION_SDK
    dry_run: bool = False
    optimize: bool = True
    optimizer_selection: str = OPTIMIZER_SELECTION_FIXED
    root_prim_path: str | None = None
    material_candidate_space: str = "source"
    skip_instances: bool = True
    skip_prototypes: bool = False
    skip_invisible: bool = False
    flatten_prototypes: bool | None = None
    enable_deinstance: bool | None = None
    enable_split: bool | None = None
    # Geometry deduplication can collapse visually identical parts that need
    # distinct material decisions, so material assignment keeps it opt-in.
    enable_deduplicate: bool | None = None
    preflight: bool = True
    respect_existing_material_bindings: bool = False
    scene_tool_timeout_seconds: float = 60.0
    material_restore_timeout_seconds: float = DEFAULT_MATERIAL_RESTORE_TIMEOUT_SECONDS
    child_timeout_seconds: float = 1800.0
    prompt_mode: str = DEFAULT_PROMPT_MODE
    vqa_refinement_max_iterations: int = DEFAULT_VQA_REFINEMENT_MAX_ITERATIONS
    codex_persistent_refinement: bool = False
    memory_enabled: bool = False
    memory_root: Path | None = None
    additional_instructions: str | None = None
    agent_cwd: Path | None = None
    parent_usd_cli_session_identity: Path | None = None
    parent_usd_cli_session_identity_sha256: str | None = None
    # Bound only by the parent-owned capability immediately before child launch.
    # Keeping it in the immutable config makes the routing contract survive any
    # dataclass serialization instead of relying on a runtime-only attribute.
    usd_cli_server_url: str | None = None
    _bridge_model_usage: _BridgeModelUsageLedger = field(
        default_factory=_BridgeModelUsageLedger,
        compare=False,
        repr=False,
    )
    _bridge_model_usage_run_dir: Path | None = field(
        default=None,
        compare=False,
        repr=False,
    )
    _usd_cli_telemetry_route_cache: _UsdCliTelemetryRouteCache | None = field(
        default=None,
        compare=False,
        repr=False,
    )


