    sweep_deadline_seconds: float = DEFAULT_SWEEP_DEADLINE_SECONDS
    tuning_phase_deadline_seconds: float | None = None
    revalidation_max_penetration_m: float | None = None
    agent_cwd: Path | None = None
    parent_usd_cli_session_identity: Path | None = None
    parent_usd_cli_session_identity_sha256: str | None = None
    usd_cli_server_url: str | None = None
    _bridge_model_usage: _BridgeModelUsageLedger = field(
        default_factory=_BridgeModelUsageLedger,
        compare=False,
        repr=False,
    )
